// Markdown→HTML — convert Slack mrkdwn to HTML for SF rich-text field
// Per §8.8
const md = $json.output_text || $json.choices?.[0]?.message?.content || '';
const { marked } = require('marked');
const cleaned = md
  .replace(/<(https?:\/\/[^|>]+)\|([^>]+)>/g, '[$2]($1)')
  .replace(/\*([^\*\n]+)\*/g, '**$1**');
const html = marked.parse(cleaned);
return [{ json: { ...$json, html, output_text: md } }];

